  var CTX_MAX_OUTLINE = 600;
  var CTX_MAX_PATH_SEGMENTS = 8;
  var CTX_MAX_CLASSES = 8;
  var CTX_MAX_ATTRS = 10;
  var CTX_MAX_ATTR_VALUE = 120;
  var CTX_MAX_CHILDREN = 6;
